 "content": "def transform(grid):
    """Connect isolated markers via the longest aligned pair as a spine."""
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]
    if len(points) < 2:
        return out
    # The principal axis is the longest pair of markers sharing a row or column.
    best = None
    for i, (r1, c1) in enumerate(points):
        for r2, c2 in points[i + 1:]:
            if r1 == r2:
                candidate = (abs(c2 - c1), 'h', r1, min(c1, c2), max(c1, c2))
            elif c1 == c2:
                candidate = (abs(r2 - r1), 'v', c1, min(r1, r2), max(r1, r2))
            else:
                continue
            if best is None or candidate[0] > best[0]:
                best = candidate
    if best is None:
        return out
    _, axis, fixed, lo, hi = best
    def paint(r, c):
        if out[r][c] == 0:
            out[r][c] = 3
    if axis == 'h':
        for c in range(lo, hi + 1):
            paint(fixed, c)
        for r, c in points:
            if lo <= c <= hi:
                for rr in range(min(r, fixed), max(r, fixed) + 1):
                    paint(rr, c)
    else:
        for r in range(lo, hi + 1):
            paint(r, fixed)
        for r, c in points:
            if lo <= r <= hi:
                for cc in range(min(c, fixed), max(c, fixed) + 1):
                    paint(r, cc)
    return out
